/bin/bash -lc "python - <<'PY'
import numpy as np
c=np.load('circle_tracks.npy');
for a,b in [(0,12),(13,32)]:
 p=np.polyfit(np.arange(a,b),c[a:b,1],2); print(a,p,'g',2*p[0])
p0=np.polyfit(np.arange(12),c[:12,1],2);p1=np.polyfit(np.arange(13,32),c[13:32,1],2); roots=np.roots(p0-p1);print('intersection',roots)
for ti in roots:
 if 10<ti<14: print('impact',ti, np.polyval(p0,ti),'v1',np.polyval(np.polyder(p1),ti),'v0',np.polyval(np.polyder(p0),ti))
PY"
